export function icon(name, size = 20, extra = '') {
  const body = P[name];
  if (!body) { console.warn('нет иконки', name); return ''; }
  return `<svg class="ic ${extra}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${body}</svg>`;
}
export const iconNames = Object.keys(P);
